        return 0

    rows = len(nums) // cols
    if rows == 0:
        return 0

    dp = [[float('inf')] * cols for _ in range(rows)]
    for c in range(cols):
        dp[0][c] = nums[c]

    for r in range(1, rows):
        for c in range(cols):
            val = nums[r * cols + c]
            dp[r][c] = val + dp[r-1][c]
            if c > 0:
                dp[r][c] = min(dp[r][c], val + dp[r-1][c-1])
            if c < cols - 1:
                dp[r][c] = min(dp[r][c], val + dp[r-1][c+1])

    return min(dp[rows-1])

